package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="spms_rating_appeal_evidence")public class PerformanceAppealEvidence extends RspAuditedEntity{@Column(name="appeal_id",nullable=false,length=36)private String appealId;@Column(name="original_filename",nullable=false,length=255)private String originalFilename;@Column(name="storage_provider",nullable=false,length=30)private String storageProvider;@Column(name="storage_object_key",nullable=false,length=500)private String storageObjectKey;@Column(name="media_type",nullable=false,length=120)private String mediaType;@Column(name="byte_size",nullable=false)private long byteSize;@Column(nullable=false,length=64)private String checksum;@Column(name="uploaded_by",nullable=false,length=100)private String uploadedBy;@Column(name="uploaded_at",nullable=false)private Instant uploadedAt;protected PerformanceAppealEvidence(){}public PerformanceAppealEvidence(String a,String appeal,String filename,String provider,String key,String media,long size,String checksum,String actor,Instant at){super(a);appealId=requiredText(appeal,"appealId");originalFilename=requiredText(filename,"originalFilename");storageProvider=requiredText(provider,"storageProvider");storageObjectKey=requiredText(key,"storageObjectKey");mediaType=requiredText(media,"mediaType");if(size<1)throw new IllegalArgumentException("byteSize must be positive");byteSize=size;this.checksum=requiredText(checksum,"checksum");uploadedBy=requiredText(actor,"actor");uploadedAt=at;}public String getAppealId(){return appealId;}public String getOriginalFilename(){return originalFilename;}public String getStorageProvider(){return storageProvider;}public String getStorageObjectKey(){return storageObjectKey;}public String getMediaType(){return mediaType;}public long getByteSize(){return byteSize;}public String getChecksum(){return checksum;}public String getUploadedBy(){return uploadedBy;}public Instant getUploadedAt(){return uploadedAt;}}
